                key = ((x + dx) % width, (y + dy) % height)
                neighbor_counts[key] = neighbor_counts.get(key, 0) + 1
    return {
        cell
        for cell, count in neighbor_counts.items()
        if count == 3 or (count == 2 and cell in cells)
    }


