        for y in range(height)
    ]
    header = f" gen {generation:>5}  alive {len(cells):>5}  (Ctrl-C to quit)"
    return "\n".join([header, "+" + "-" * width + "+"] + [f"|{line}|" for line in lines] + ["+" + "-" * width + "+"])


